import re
import shutil
from pathlib import Path

ACTIVE_ROOT = Path("/srv/travel/documents/active")
ARCHIVE_ROOT = Path("/srv/travel/documents/archive")


def archive_trip_documents(trip_id: str, archive_year: int) -> dict:
    if not trip_id or not re.fullmatch(r"[A-Za-z0-9_-]{4,40}", trip_id):
        return {"ok": False, "error": "Invalid trip_id."}
    if archive_year < 2000 or archive_year > 2100:
        return {"ok": False, "error": "archive_year is out of range."}
    source = ACTIVE_ROOT / trip_id
    if not source.is_dir():
        return {"ok": False, "error": f"No active document folder for trip {trip_id}."}
    files = sorted(p.name for p in source.iterdir() if p.is_file())
    if not files:
        return {"ok": False, "error": "Trip folder has no documents to archive."}
    destination = ARCHIVE_ROOT / str(archive_year) / trip_id
    if destination.exists():
        return {"ok": False, "error": f"Archive folder already exists at {destination}."}
    destination.parent.mkdir(parents=True, exist_ok=True)
    shutil.move(str(source), str(destination))
    return {"ok": True, "trip_id": trip_id, "archived_to": str(destination), "files": files}
